function documentLanguageLabel(code?:string){const normalized=(code||'').trim().toLowerCase().split('-',1)[0];if(normalized==='mixed')return 'Multilingual';if(normalized==='und')return 'Unknown';return languages.find(([value])=>value===normalized)?.[1]||code||''}
function isPdf(file:File){return file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')}
export const api=async(path:string,init:RequestInit={})=>{const headers=init.body instanceof FormData?init.headers:{'Content-Type':'application/json',...(init.headers||{})};const r=await fetch(API+path,{...init,headers,credentials:'include'});const d=await r.json().catch(()=>({}));if(!r.ok){console.warn('[IntelliGround API] request failed',{endpoint:path,status:r.status,detail:d.detail||d.message});const detail=typeof d.detail==='string'?d.detail:(d.detail?.message||d.detail?.reason||d.message);const error=Error(detail||`Request failed (${r.status})`);const typed=error as Error&{status?:number;code?:string;requiresConfirmation?:boolean};typed.status=r.status;typed.code=typeof d.detail==='object'?d.detail?.code:undefined;typed.requiresConfirmation=typeof d.detail==='object'?d.detail?.requires_confirmation:undefined;throw error}return d}
